import {usePluginStore,useWatchEvent} from '@/hooks/plugin';import {WoodPhotoRenderer,WoodPhotoState,loadWoodPhotoAssets,woodPhotoValues} from '@/wood-photo-clock';
export default function(name:string){const plugin=usePluginStore(),ActionID=window.argv[3].plugin.uuid+'.'+name,items=new Map<string,any>();function stop(context:string){plugin.Unterval(ActionID+context);items.delete(context);}async function start(context:string){stop(context);const st={renderer:new WoodPhotoRenderer(),clock:new WoodPhotoState(),ready:false,busy:false,last:''};items.set(context,st);try{await loadWoodPhotoAssets();if(items.get(context)!==st)return;st.ready=true;draw(context,true);plugin.Interval(ActionID+context,33,()=>draw(context));}catch(e){console.error(JSON.stringify({event:'wood_photo_asset_error',error:String(e)}));}}function draw(context:string,force=false){const st=items.get(context),a=plugin.getAction(context);if(!st?.ready||!a||st.busy)return;const s=a.settings as any,now=performance.now();st.clock.update(woodPhotoValues(new Date(),s.hour12===true),now);const p=st.clock.progress(now,s),key=JSON.stringify(s)+st.clock.revision+':'+p;if(!force&&st.last===key)return;const canvas=st.renderer.draw(st.clock.from,st.clock.to,p,s);if(s.transport==='binary'){st.busy=true;canvas.toBlob(async blob=>{try{if(blob&&items.get(context)===st){a.setImageBlob(await blob.arrayBuffer(),'image/png');st.last=key;}}finally{st.busy=false;}},'image/png');}else try{a.setImage(canvas.toDataURL('image/jpeg',.95));st.last=key;}catch(e){console.error(JSON.stringify({event:'wood_photo_send_error',error:String(e)}));}}useWatchEvent('action',{ActionID,willAppear:({context})=>start(context),willDisappear:({context})=>stop(context),didReceiveSettings:({context})=>draw(context,true)});}
